pub fn cellAttrSlot(attr_name: []const u8) ?usize {
    if (std.mem.eql(u8, attr_name, "position")) {
        return 0;
    }
    if (std.mem.eql(u8, attr_name, "inst_pos")) {
        return 1;
    }
    if (std.mem.eql(u8, attr_name, "inst_size")) {
        return 2;
    }
    if (std.mem.eql(u8, attr_name, "inst_color")) {
        return 3;
    }
    return null;
}
