    return null;
}
pub fn cellUniformOffset(ub_name: []const u8, u_name: []const u8) ?usize {
    if (std.mem.eql(u8, ub_name, "vs_params")) {
        if (std.mem.eql(u8, u_name, "camera_pos")) {
            return 0;
        }
        if (std.mem.eql(u8, u_name, "zoom")) {
            return 8;
        }
        if (std.mem.eql(u8, u_name, "viewport_size")) {
            return 16;
        }
    }
    return null;
}
pub fn cellUniformDesc(ub_name: []const u8, u_name: []const u8) ?sg.GlslShaderUniform {
    if (std.mem.eql(u8, ub_name, "vs_params")) {
        if (std.mem.eql(u8, u_name, "camera_pos")) {
            var desc: sg.GlslShaderUniform = .{};
            desc.type = .FLOAT2;
            desc.array_count = 0;
            desc.glsl_name = "camera_pos";
            return desc;
        }
        if (std.mem.eql(u8, u_name, "zoom")) {
            var desc: sg.GlslShaderUniform = .{};
            desc.type = .FLOAT;
