            return desc;
        }
        if (std.mem.eql(u8, u_name, "viewport_size")) {
            var desc: sg.GlslShaderUniform = .{};
            desc.type = .FLOAT2;
            desc.array_count = 0;
            desc.glsl_name = "viewport_size";
            return desc;
        }
    }
    return null;
}
